{{define "app-page-view-page-heading"}} <div class="page-heading apps-heading"><div><h1>{{.AppsTitle}}</h1></div>
 <div class="apps-toolbar"><a class="control-icon-button" href="/settings/apps/service" aria-label="{{.AppSettings}}" title="{{.AppSettings}}">{{.SettingsIcon}}</a>{{if .SearchVisible}}<form method="get" action="/settings/apps" class="apps-search control-search" role="search"><input type="hidden" name="view" value="all"><input type="hidden" name="category" value="{{.Category}}"><label for="app-search" class="sr-only">{{.SearchApps}}</label><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input type="search" id="app-search" name="search" value="{{.SearchValue}}" maxlength="200" placeholder="{{.SearchApps}}"><button class="sr-only" type="submit">{{.Search}}</button></form>{{end}}<a class="control-icon-button" href="/settings/apps" aria-label="{{.RefreshApps}}" title="{{.RefreshApps}}"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/></svg></a></div></div>
{{end}}
{{define "app-page-view-page-unavailable"}} {{if .Unavailable}}<p class="apps-notice" role="alert">{{.DirectoryUnavailable}}</p>{{end}}
{{end}}
{{define "app-page-view-page-feedback"}} <p class="feedback" role="status" aria-live="polite" data-app-feedback hidden></p>
{{end}}
{{define "app-page-view-page-inventory"}} <div id="app-accounts" hidden>{{.Inventory}}</div>
{{end}}
{{define "app-page-view-page-body"}} {{if .Selected}}<a class="back-link" href="/settings/apps">{{.BackToApps}}</a><section class="app-detail-page">{{.Detail}}</section>{{else}}
{{.Directory}} {{end}}
{{end}}
{{define "app-page-view-page-dialog"}} <dialog class="control-dialog apps-dialog" data-app-dialog aria-labelledby="app-dialog-title"><button type="button" class="control-icon-button apps-dialog-close" data-app-close aria-label="{{.Close}}"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg></button><div data-app-dialog-body></div></dialog>
{{end}}
{{define "app-page-view-detail-heading"}}{{if .Selected}}<header>{{.Icon}}<div><h2>{{.Name}}</h2><p>{{.Description}}</p></div></header>
{{end}}{{end}}
{{define "app-page-view-detail-feedback"}}{{if .Selected}}<p class="feedback" data-app-detail-feedback role="status" aria-live="polite" hidden></p>
{{end}}{{end}}
{{define "app-page-view-detail-accounts"}}{{if .Selected}}<h3>{{.YourConnections}}</h3><div data-app-detail-accounts>{{.Accounts}}</div><p class="muted" data-app-no-accounts {{if .EmptyHidden}}hidden{{end}}>{{.NoConnections}}</p>
{{end}}{{end}}
{{define "app-page-view-service-heading"}} <div class="page-heading"><div><h1>{{.ServiceTitle}}</h1></div></div>
{{end}}
{{define "app-page-view-service-back"}} <a class="back-link" href="/settings/apps">{{.BackToApps}}</a>
{{end}}
{{define "app-page-view-page"}}
<section class="workspace-page settings-page apps-page" data-apps data-app-revision="{{.Revision}}" data-app-interface-mode="{{.InterfaceMode}}" data-app-interface-revision="{{.InterfaceRevision}}" data-app-interface-profile="{{.InterfaceProfile}}"{{if .Localized}} data-app-interface-localized="true"{{end}}>
{{.Body}}</section>
{{end}}

{{define "app-page-view-service"}}
<section class="workspace-page settings-page">
{{.Body}}</section>
{{end}}

{{define "app-page-view-sidebar"}}
{{if .ManagedPresent}}<p class="settings-nav-heading apps-sidebar-heading">{{.ConnectedApps}}</p><nav class="section-navigation apps-connections" aria-label="{{.ConnectedApps}}">{{.Entries}}</nav>{{end}}
{{end}}
{{define "app-page-view-detail"}}
{{if .Selected}}<div class="app-detail" data-app-detail="{{.Slug}}"{{if .HasInterface}} data-app-no-auth="{{.NoAuth}}" data-app-suggested="{{.Suggested}}"{{end}}>{{.Body}}</div>{{end}}
{{end}}

{{define "app-page-view-account-row"}}<div class="app-account" data-app-account="{{.ID}}" data-app-slug="{{.Toolkit}}" data-app-state="{{.Status}}" data-app-public="{{.Public}}">{{.Body}}</div>{{end}}
{{define "app-page-view-accounts"}}
{{.Accounts}}
{{end}}

{{define "app-page-view-group"}}<section class="apps-group"><div class="apps-group-heading"><h2>{{.Title}}</h2>{{if .HasURL}}<a class="text-link" href="{{.URL}}" aria-label="{{.ViewAll}}: {{.Title}}">{{.ViewAll}}<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></a>{{end}}</div><div class="apps-grid">{{.Cards}}</div></section>{{end}}
{{define "app-page-view-groups"}} {{if .GroupsPresent}}{{.Groups}}{{else}}<p class="apps-empty">{{.NoApps}}</p>{{end}}
{{end}}
